"use client";

import { useRef, useState, useCallback } from "react";

/* ============================================================
   TEAM CARD — Box-Reveal Animation (White Clay Theme)

   Faithfully adapted from the reference team-box-reveal.html.
   Uses the exact same base64 ornate embossed pattern on the flaps.
   Flaps swing open on hover/tap to reveal the team photo.

   White Sculptural Tactility theme applied to:
   - Card wrapper background
   - Text colors (on-surface, outline)
   - Photo border
   ============================================================ */

const CARD_IMG = "data:image/jpeg;base64,";

interface TeamCardProps {
  name: string;
  role: string;
  photo?: string;
}

export default function TeamCard({ name, role, photo }: TeamCardProps) {
  const [open, setOpen] = useState(false);
  const cardRef = useRef<HTMLDivElement>(null);

  const toggle = useCallback(() => setOpen((o) => !o), []);

  return (
    <>
      <style>{`
        .tc-wrap {
          display: flex;
          flex-direction: column;
          align-items: center;
        }
        .tc-card {
          perspective: 1200px;
          perspective-origin: 50% 50%;
          height: 420px;
          cursor: pointer;
          -webkit-tap-highlight-color: transparent;
        }
        .tc-stage {
          position: relative;
          width: 100%;
          height: 360px;
        }

        /* Inner box — appears behind the photo when flaps open */
        .tc-inner {
          position: absolute;
          left: 50%;
          top: 6%;
          width: 70%;
          height: 88%;
          transform: translate(-50%, 0) scale(0.7);
          opacity: 0;
          border-radius: 4px;
          background-color: var(--surface-container-high, #e8e7f1);
          background-image: url("${CARD_IMG}");
          background-repeat: no-repeat;
          background-position: center top;
          background-size: cover;
          box-shadow:
            0 10px 26px rgba(0, 0, 0, 0.06),
            inset 0 0 0 1px var(--outline-variant, #c7c6cb);
          transition:
            transform 0.6s cubic-bezier(0.2, 0.8, 0.2, 1) 0.08s,
            opacity 0.5s ease 0.08s;
          z-index: 1;
        }
        .tc-card:hover .tc-inner,
        .tc-card.open .tc-inner {
          transform: translate(-50%, 0) scale(0.88);
          opacity: 1;
        }

        /* Photo — revealed behind flaps */
        .tc-photo {
          position: absolute;
          left: 50%;
          bottom: 8px;
          width: 78%;
          height: 88%;
          border-radius: 3px;
          overflow: hidden;
          transform: translate(-50%, 10%) scale(0.9);
          opacity: 0;
          transition:
            transform 0.55s cubic-bezier(0.2, 0.8, 0.2, 1) 0.16s,
            opacity 0.5s ease 0.16s;
          z-index: 2;
          background: #000;
          box-shadow: 0 18px 40px rgba(0, 0, 0, 0.1);
        }
        .tc-photo img {
          width: 100%;
          height: 100%;
          object-fit: cover;
          display: block;
          filter: grayscale(0.1) contrast(1.05);
        }
        .tc-photo::after {
          content: "";
          position: absolute;
          inset: 0;
          border: 1px solid var(--outline-variant, #c7c6cb);
          pointer-events: none;
        }
        .tc-card:hover .tc-photo,
        .tc-card.open .tc-photo {
          transform: translate(-50%, -14%) scale(1);
          opacity: 1;
        }

        /* Flaps — ornate embossed pattern, split left/right */
        .tc-flap {
          position: absolute;
          top: 0;
          width: 50%;
          height: 100%;
          background-repeat: no-repeat;
          background-image: url("${CARD_IMG}");
          background-size: 200% 100%;
          border: 1px solid #000;
          z-index: 3;
          backface-visibility: hidden;
          transition: transform 0.6s cubic-bezier(0.3, 0.7, 0.2, 1);
          transform-style: preserve-3d;
        }
        .tc-flap-l {
          left: 0;
          border-radius: 6px 0 0 6px;
          background-position: left top;
          transform-origin: left center;
          box-shadow: inset -1px 0 0 rgba(0, 0, 0, 0.15);
        }
        .tc-flap-r {
          right: 0;
          border-radius: 0 6px 6px 0;
          background-position: right top;
          transform-origin: right center;
        }
        .tc-card:hover .tc-flap-l,
        .tc-card.open .tc-flap-l {
          transform: rotateY(-140deg);
        }
        .tc-card:hover .tc-flap-r,
        .tc-card.open .tc-flap-r {
          transform: rotateY(140deg);
        }

        @media (prefers-reduced-motion: reduce) {
          .tc-flap, .tc-photo, .tc-inner { transition: none; }
        }
      `}</style>

      <div className="tc-wrap">
        <div
          ref={cardRef}
          className={`tc-card${open ? " open" : ""}`}
          onClick={toggle}
        >
          <div className="tc-stage">
            <div className="tc-inner" />
            <div className="tc-photo">
              {photo ? (
                <img src={photo} alt={name} loading="lazy" />
              ) : (
                <div
                  style={{
                    width: "100%",
                    height: "100%",
                    background: "linear-gradient(135deg, #e8e7f1, #c7c6cb)",
                    display: "flex",
                    alignItems: "center",
                    justifyContent: "center",
                    fontFamily: "'Syne', sans-serif",
                    fontWeight: 800,
                    fontSize: 48,
                    color: "var(--on-surface-variant, #46464b)",
                  }}
                >
                  {name.split(" ").map((w) => w[0]).join("")}
                </div>
              )}
            </div>
            <div className="tc-flap tc-flap-l" />
            <div className="tc-flap tc-flap-r" />
          </div>
        </div>

        {/* Info below card */}
        <div style={{ textAlign: "center", marginTop: 16 }}>
          <p
            style={{              fontFamily: "'CremeEspana', cursive",
              color: "var(--on-surface, #1a1b22)",
              fontSize: 24,
              fontWeight: 400,
              margin: 0,
            }}
            >
            {name}
          </p>
          <p
            style={{
              color: "var(--outline, #77767b)",
              fontSize: 12,
              letterSpacing: "0.08em",
              textTransform: "uppercase",
              margin: "3px 0 0",
              fontFamily: "'Plus Jakarta Sans', sans-serif",
              fontWeight: 500,
            }}
          >
            {role}
          </p>
        </div>
      </div>
    </>
  );
}
